package com.ems.controller; import com.ems.dao.EmployeeDAO; import com.ems.model.Employee; import com.ems.util.InputValidator; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException; import java.math.BigDecimal; import java.time.LocalDate; import java.util.Map;
@WebServlet("/employees/save") public class EmployeeSaveServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{String id=r.getParameter("employeeId");Map<String,String> errors=InputValidator.employee(r.getParameter("fullName"),r.getParameter("email"),r.getParameter("phone"),r.getParameter("department"),r.getParameter("designation"),r.getParameter("salary"),r.getParameter("joiningDate"),r.getParameter("employmentStatus"));if(!errors.isEmpty()){r.setAttribute("errors",errors);r.setAttribute("form",r.getParameterMap());r.getRequestDispatcher(id==null?"/WEB-INF/views/add-employee.jsp":"/WEB-INF/views/edit-employee.jsp").forward(r,s);return;}try{Employee e=new Employee();if(id!=null)e.setEmployeeId(Long.parseLong(id));e.setFullName(r.getParameter("fullName").trim());e.setEmail(r.getParameter("email").trim());e.setPhone(r.getParameter("phone").trim());e.setDepartment(r.getParameter("department"));e.setDesignation(r.getParameter("designation").trim());e.setSalary(new BigDecimal(r.getParameter("salary")));e.setJoiningDate(LocalDate.parse(r.getParameter("joiningDate")));e.setEmploymentStatus(r.getParameter("employmentStatus"));e.setAddress(r.getParameter("address"));if(id==null)new EmployeeDAO().insert(e);else new EmployeeDAO().update(e);s.sendRedirect(r.getContextPath()+"/employees?success="+(id==null?"added":"updated"));}catch(Exception e){getServletContext().log("Employee save failed",e);r.setAttribute("error",e.getMessage()!=null&&e.getMessage().contains("Duplicate")?"That email address is already in use.":"Unable to save the employee.");r.getRequestDispatcher(id==null?"/WEB-INF/views/add-employee.jsp":"/WEB-INF/views/edit-employee.jsp").forward(r,s);}}}
